function parseScaleNumber(text, scaleMin = 1, scaleMax = 5) {
  const n = Number(String(text || '').trim());

  if (!Number.isInteger(n)) return null;
  if (n < Number(scaleMin) || n > Number(scaleMax)) return null;

  return n;
}

