  const rows = await supabase(
    `whatsapp_profile_links?phone=eq.${encodeURIComponent(phone)}&status=eq.active&select=*`,
    { method: 'GET' }
  );

  return rows?.[0] || null;
}

async function getProfileByEmail(email) {
  const normalizedEmail = String(email || '').trim().toLowerCase();

  const rows = await supabase(
    `profiles?email=eq.${encodeURIComponent(normalizedEmail)}&select=*&limit=1`,
    { method: 'GET' }
  );

  const profile = rows?.[0] || null;

  if (!profile) return null;

  return {
    id: profile.id,
    user_id: profile.user_id,
    tenant_id: profile.tenant_id || null,
    nome: profile.nome || profile.name || null,
    email: profile.email,
    telefone: profile.telefone || profile.phone || null
  };
}

async function getState(phone) {
  const rows = await supabase(
    `whatsapp_conversation_state?phone=eq.${encodeURIComponent(phone)}&expires_at=gt.now()&select=*&limit=1`,
    { method: 'GET' }
  );

  return rows?.[0] || null;
}

async function upsertState(phone, step, payload, ids = {}) {
  const row = {
    phone,
    user_id: ids.user_id || payload.user_id || null,
    profile_id: ids.profile_id || payload.profile_id || null,
    tenant_id: ids.tenant_id || payload.tenant_id || null,
    current_step: step,
    payload,
    updated_at: new Date().toISOString(),
    expires_at: new Date(Date.now() + 2 * 60 * 60 * 1000).toISOString()
  };

  return await supabase('whatsapp_conversation_state?on_conflict=phone', {
    method: 'POST',
    prefer: 'resolution=merge-duplicates,return=representation',
    body: JSON.stringify(row)
  });
}

