  if (!currentConfig) {
    const fallbackStartPayload = await buildDiaryStartPayload(
      link.user_id,
      payload.entry_date || todayISO()
    );

    await upsertState(msg.phone, 'WAITING_EMOTION_SCORE', fallbackStartPayload, link);

