const errorData = $input.first().json;
const n8nHttpRequest = this.helpers.httpRequest.bind(this.helpers);

const SUPABASE_URL = (process.env.SUPABASE_URL || '').replace(/\/+$/, '');
const SUPABASE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY || '';

const errorLog = {
  workflow: 'ai-agent-diario-emocional',
  node: errorData.execution?.lastNodeExecuted || 'unknown',
  error_code: 'WORKFLOW_UNHANDLED_ERROR',
  message: errorData.execution?.error?.message || 'Unknown error',
  timestamp: new Date().toISOString()
};

if (SUPABASE_URL && SUPABASE_KEY) {
  try {
    await n8nHttpRequest({
      method: 'POST',
      url: `${SUPABASE_URL}/rest/v1/workflow_error_logs`,
      headers: {
        apikey: SUPABASE_KEY,
        Authorization: `Bearer ${SUPABASE_KEY}`,
        Prefer: 'return=minimal',
        'Content-Type': 'application/json'
      },
      json: true,
      body: errorLog
    });
  } catch (e) {}
}

return [{ json: { logged: true, error: errorLog } }];
